#include <bits/stdc++.h>
using namespace std;

int main() {
    string n;
    int k;
    cin >> n >> k;

    int zeros = 0, removed = 0;

    for (int i = static_cast<int>(n.size()) - 1; i >= 0 && zeros < k; --i) {
        if (n[i] == '0')
            ++zeros;
        else
            ++removed;
    }

    cout << (zeros == k ? removed : static_cast<int>(n.size()) - 1);
    return 0;
}

